import{A as e,H as t,V as n,et as r}from"./chunks/framework.B1PU1n-w.js";var i=JSON.parse(`{"title":"账号管理","description":"","frontmatter":{},"headers":[],"relativePath":"features/account.md","filePath":"features/account.md"}`),a={name:`features/account.md`};function o(e,i,a,o,s,c){return r(),n(`div`,null,[...i[0]||=[t(`<h1 id="账号管理" tabindex="-1">账号管理 <a class="header-anchor" href="#账号管理" aria-label="Permalink to “账号管理”">​</a></h1><p>Syncraft 内置了一个定制的 <a href="https://yushijinhun.github.io/authlib-injector/en/yggdrasil-server-technical-specification.html" target="_blank" rel="noreferrer">Yggdrasil</a> 服务，用于管理玩家账户。这使得 Syncraft 得以脱离各种登录方式混杂的状况，并将各种权利最大限度地留给腐竹。</p><h2 id="配置-yggdrasil" tabindex="-1">配置 Yggdrasil <a class="header-anchor" href="#配置-yggdrasil" aria-label="Permalink to “配置 Yggdrasil”">​</a></h2><p>在 <code>syncraft.toml</code> 中，进行你的 yggdrasil 登录服务的配置：</p><div class="language-toml"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">yggdrasil</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># 可选，yggdrasil 服务在其 meta 接口上显示的服务名</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">server_name = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;syncraft-yggdrasil&quot;</span></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># yggdrasil 服务的外部访问链接，格式为 \`&lt;syncraft-server 链接&gt;/yggdrasil\`</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">base_url = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;http://myserver.com/yggdrasil&quot;</span></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># 皮肤域名，必须将你 syncraft 服务的域名填入以使用 syncraft 的皮肤服务；</span></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># 另外添加 &quot;littleskin.cn&quot; 将 Littleskin 作为皮肤 fallback 。</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">skin_domains = [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;myserver.com&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;littleskin.cn&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># 身份伪造功能，开启后，玩家加入服务器不需要在 syncraft 登录。</span></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># 开启时，syncraft 账号的皮肤和正版皮肤依然能在服务器里显示。</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">identity_falsification = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># 可选，当无此项时，账号无需经过邮件验证即可注册。</span></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># 如果你的服务器都是熟人玩，倒是可以不填。</span></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># 在互联网上搜索你的邮件服务商 + smtp 学习如何配置该服务。</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">yggdrasil</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">email</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">smtp_host = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;smtp.example.com&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">smtp_port = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">587</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">username = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;noreply@example.com&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">password = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;your_smtp_password&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">from_name = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;WELCOME TO MY SERVER&quot;</span></span></code></pre></div><p>哪怕是正版账号来了，他们也得在 Syncraft 注册！但作为高贵的正版玩家，他们不需要特意配置皮肤，syncraft-server 会自动将正版皮肤转发到 Minecraft 服务器。</p><div class="tip custom-block"><p class="custom-block-title custom-block-title-default">TIP</p><p>如果你没有正版账户，或者你想临时使用别的皮肤，你可以在用 syncraft-core 启动游戏时，在它所在的目录中放置你的皮肤文件，并重命名为 <code>skin.png</code>， syncraft-core 将自动上传它。</p></div><h2 id="手动管理账户" tabindex="-1">手动管理账户 <a class="header-anchor" href="#手动管理账户" aria-label="Permalink to “手动管理账户”">​</a></h2><p>syncraft-server提供了一系列指令来手动管理账户。如果你的服务器成员感到注册账号太麻烦了，你也可以帮他们注册。</p><p>列出当前有效的所有账户：</p><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">syncraft</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> account</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span></span></code></pre></div><p>添加账户，用法为 <code>syncraft account add</code> + 邮箱 + 角色名 + 密码：</p><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">syncraft</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> account</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> email@example.com</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> CharName</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my_strong_password</span></span></code></pre></div><p>手动添加的账户将自动通过邮箱验证。</p><p>移除账户，用法为 <code>syncraft account remove</code> + 角色名：</p><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">syncraft</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> account</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> remove</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> CharName</span></span></code></pre></div>`,16)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};